"""Prepare OpenTrip for an episode.

OpenTrip's episodes start on its sign-in page: a signed-out session with the
episode's account prefilled.  The loopback session endpoint reports the
signed-out state; the prefilled account is part of the page itself, so
preparation confirms it from the guest's own window tree.  It signs nothing in,
creates no booking, adds no baggage and writes no document.
"""

from __future__ import annotations

from typing import Any, Mapping

from evaluators.cua_review.core.initialization import InitializationError, MacAppInitializer

#: Port OpenTrip serves on inside the guest.
DEFAULT_PORT = 4330

#: How long the sign-in page is given to render.
DEFAULT_VISIBLE_TIMEOUT_SECONDS = 45.0


class OpenTripInitializer(MacAppInitializer):
    """Confirm the signed-out OpenTrip starting point an episode assumes."""

    INITIALIZER_ID = "initializers.macos.opentrip:OpenTripInitializer"
    APP_NAME = "OpenTrip"
    BUNDLE_ID = "local.osomni.opentrip"
    SETTLE_MS = 2500

    def verify_preconditions(self, controller: Any, params: Mapping[str, Any]) -> str:
        port, state, notes = self._read_loopback(
            controller,
            [params.get("port") or DEFAULT_PORT],
            ["/api/session"],
            what="OpenTrip state",
        )
        if port is None:
            raise InitializationError(
                "OpenTrip did not answer GET /api/session"
                + (f" ({'; '.join(notes)})" if notes else "")
            )
        session = dict(self._endpoint_body(state, "/api/session").get("session") or {})

        expected_logged_in = bool(params.get("expected_logged_in"))
        observed_logged_in = bool(session.get("loggedIn") or session.get("user"))
        if observed_logged_in != expected_logged_in:
            raise InitializationError(
                f"OpenTrip signed-in state is {observed_logged_in}, expected {expected_logged_in}"
            )

        account = dict((params.get("expected_seed") or {}).get("account") or {})
        # The sign-in page identifies the account by its phone number and offers
        # the password field; the account's display name is not shown until the
        # session is open, so the phone number is what confirms the prefill.
        markers = [
            account.get("phone"),
            params.get("expected_sign_in_label") or "Sign In",
        ]
        timeout = float(params.get("visible_timeout_seconds") or DEFAULT_VISIBLE_TIMEOUT_SECONDS)
        self._wait_for_visible(
            controller,
            markers,
            timeout=timeout,
            what="the OpenTrip sign-in page",
        )

        return (
            f"OpenTrip answers on port {port}, signed_in={observed_logged_in}, "
            f"with the {account.get('name') or 'expected'} account prefilled on its sign-in page"
        )
